<?php
namespace App\Models;
use App\Traits\BelongsToOrganization;use Illuminate\Database\Eloquent\Casts\Attribute;use Illuminate\Database\Eloquent\Concerns\HasUuids;use Illuminate\Database\Eloquent\Factories\HasFactory;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\SoftDeletes;use Illuminate\Support\Facades\Crypt;
class DigitalCertificate extends Model{use BelongsToOrganization,HasFactory,HasUuids,SoftDeletes;protected $guarded=[];protected $hidden=['password_encrypted'];protected $attributes=['certificate_type'=>'A1','environment'=>'production','alert_days_before'=>30,'status'=>'active'];protected function casts():array{return ['purposes'=>'array','issued_at'=>'date','expires_at'=>'date','is_primary'=>'boolean','metadata'=>'array'];}protected function certificatePassword():Attribute{return Attribute::make(get:fn()=>null,set:fn(?string $v):array=>filled($v)?['password_encrypted'=>Crypt::encryptString($v)]:[]);}public function company():BelongsTo{return $this->belongsTo(Company::class);}public function getDaysToExpireAttribute():?int{return $this->expires_at?->diffInDays(today(),false)*-1;}}
